import{e as t,ab as a,a1 as i,m as n,r as o,p as s}from"./chunks/framework.BGh0NSIy.js";const c=JSON.parse('{"title":"Monthly Updates [January]","description":"January 2026 updates","frontmatter":{"title":"Monthly Updates [January]","description":"January 2026 updates","date":"2026-01-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/jan-2026.md","filePath":"posts/jan-2026.md"}'),l={name:"posts/jan-2026.md"};function h(d,e,p,f,m,g){const r=a("Post");return i(),n("div",null,[o(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added <strong><a href="https://ffmhy.pages.dev/" target="_blank" rel="noreferrer">Alternative Frontend</a></strong> of FMHY with a totally different design. This pulls from the official source, so it will stay synced with new edits. It also has a <a href="https://i.ibb.co/fVkHqhRP/image.png" target="_blank" rel="noreferrer">random site</a> / <a href="https://i.imgur.com/p4Mxs8y.png" target="_blank" rel="noreferrer">2</a> button that works per page. Note the front page for this has been removed, and it now directs to the wiki itself. Thank you to nw for making this.</p></li><li><p>Added <strong><a href="https://fmhy.net/other/backups" target="_blank" rel="noreferrer">3 New Instances</a></strong> to our Backups Page (Samidy, JBugel, ArtistGrid).</p></li><li><p>Added <strong><a href="https://i.ibb.co/Ps8vDJL0/image.png" target="_blank" rel="noreferrer">Catppuccin</a></strong> / <a href="https://i.imgur.com/558l4gH.png" target="_blank" rel="noreferrer">2</a> as an option in our color picker. Thank you to Samidy for doing this.</p></li><li><p>Added a new section for <a href="https://fmhy.net/reading#textbooks" target="_blank" rel="noreferrer">Textbooks</a>.</p></li><li><p>Added a new section for <a href="https://fmhy.net/file-tools#file-info-metadata" target="_blank" rel="noreferrer">File Info / Metadata</a>.</p></li><li><p>Merged Linux + Mac Torrent Clients into the <a href="https://fmhy.net/torrenting#torrent-clients" target="_blank" rel="noreferrer">Main Section</a>, and added labels + platform icons. <a href="https://i.ibb.co/fV1zdt44/Untitled.jpg" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/THLiMqL.jpeg" target="_blank" rel="noreferrer">2</a></p></li><li><p>Re-ordered <a href="https://fmhy.net/reading#light-novels" target="_blank" rel="noreferrer">Light Novel Sites</a> based on library size and UI, added labels, removed small libraries, and starred two that stood out (NovelCool + WuxiaClick). <a href="https://i.ibb.co/DSRfsrM/Untitled.png" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/IMRUQoo.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Debloated the <a href="https://fmhy.net/audio#curated-recommendations" target="_blank" rel="noreferrer">Audio Recommendation</a> section + added a new section for <a href="https://fmhy.net/audio#song-artist-discovery" target="_blank" rel="noreferrer">Song / Artist Discovery</a>. <a href="https://i.ibb.co/zTDNZgr9/Untitled.png" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/V6h0mQx.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added Labels to both <a href="https://fmhy.net/linux-macos#cli-cheat-sheets" target="_blank" rel="noreferrer">Linux Cheat Sheets</a> + <a href="https://fmhy.net/linux-macos#linux-distros" target="_blank" rel="noreferrer">Linux Distros</a>. Thank you to <a href="https://github.com/fmhy/edit/commit/9a9cd6dd47027ac63370b453ec86a943cdc0b9d6" target="_blank" rel="noreferrer">helxop</a>. <a href="https://ibb.co/gMD8mKbw" target="_blank" rel="noreferrer">Before vs. After</a> / <a href="https://i.imgur.com/hqqLsCB.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Revamped our <a href="https://i.ibb.co/JjpzRXL7/image.png" target="_blank" rel="noreferrer">Feedback Window</a> / <a href="https://i.imgur.com/nODLPVM.png" target="_blank" rel="noreferrer">2</a> to try to improve its look. Thank you to Samidy for doing this.</p></li><li><p>Added a backup / frontend for our <a href="https://fmhy-grading.pages.dev/" target="_blank" rel="noreferrer">Grading Page</a>, and moved both our <a href="https://fmhy.net/other/backups" target="_blank" rel="noreferrer">Backup</a> + <a href="https://fmhy.net/other/FAQ" target="_blank" rel="noreferrer">FAQ</a> pages to our website instead of Reddit/GitHub. Thank you to Roi Goat + Samidy for doing this.</p></li><li><p>Improved our <a href="https://github.com/fmhy/edit/pull/4386" target="_blank" rel="noreferrer">theme handler</a>, which will help us more easily switch or add themes in the future (like Halloween, Christmas, etc.). Thank you to Land for doing this.</p></li><li><p>Added 360 Total Security to unsafe sites. If you install any of their apps, it will keep giving the user popups to install their &quot;toolbox,&quot; or will install it without consent if you use clean, repair, or optimize options. Once installed, the toolbox will then <a href="https://en.wikipedia.org/wiki/Criticism_of_Qihoo_360#Malicious_promotion" target="_blank" rel="noreferrer">modify your default apps</a> (such as your browser) and switch them all to 360 options.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/video#download-sites" target="_blank" rel="noreferrer">DDLBase</a> in Video Download. Has both 4K + 1080p content, uses only fast hosts, and has a huge library.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Anime Realms</a> in Anime Streaming. Good sources, nice UI, auto-next, custom player, and multi-language support.</p></li><li><p>Starred <a href="https://fmhy.net/audio#telegram-bots" target="_blank" rel="noreferrer">Music Hunters</a> in Telegram Audio Bots. Supports lots of sites, has good quality, and is easy to use.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#download-games" target="_blank" rel="noreferrer">AstralGames</a> in Game Downloading. Big library, fast hosts, pre-installs, and allows requests.</p></li><li><p>Starred <a href="https://fmhy.net/reading#manga" target="_blank" rel="noreferrer">Comix</a> in Manga Sites. Big library, allows uploads, nice UI, and will be adding more languages soon.</p></li><li><p>Starred <a href="https://fmhy.net/audio#streaming-sites" target="_blank" rel="noreferrer">Monochrome</a> in Audio Streaming. No sign-up needed, multi-API integrations, Last.fm integration, customizable, and a big library.</p></li><li><p>Starred <a href="https://fmhy.net/video" target="_blank" rel="noreferrer">Rive, Aether, Willow, and FlyX</a> in Streaming. These have nice custom players, lots of features, fast streams, and impressive UIs.</p></li><li><p>Starred <a href="https://fmhy.net/video#live-sports" target="_blank" rel="noreferrer">StreamSports99</a> in Live Sports. Has fast servers and a solid UI.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#twitter-x-customization" target="_blank" rel="noreferrer">Control Panel for Twitter</a> in Twitter/X Customization. Adds a lot of extra features, lets you hide sections you don&#39;t use, improves UI, and much more.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-hosts" target="_blank" rel="noreferrer">Rootz</a> in File Hosts. Good speed, 25GB per file, and lasts 15 days after the last download.</p></li><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">PigenAI</a> in Image Gen. Has unlimited Imagen 4, Qwen, and Nano Banana.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#ios-streaming" target="_blank" rel="noreferrer">Nuvio</a> in iOS Streaming. This uses Stremio plugins and has fewer limits than the &quot;Lite&quot; version currently available on iOS.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-torrenting" target="_blank" rel="noreferrer">Flud</a> in Android Torrenting. Allows binding, is well-maintained, and ads can easily be blocked via DNS.</p></li><li><p>Starred <a href="https://fmhy.net/misc#physical-health" target="_blank" rel="noreferrer">Sleeping Guide</a> in Physical Health. A sleep hygiene/science guide; seems to be well-received so far, curated by Dan.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#remakes-recreations" target="_blank" rel="noreferrer">OpenMW</a> in Remakes / Recreations. Complete ground-up reimplementation of Morrowind, <a href="https://wiki.openmw.org/index.php?title=Bethesda_Emails" target="_blank" rel="noreferrer">approved by Bethesda</a> themselves.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#remakes-recreations" target="_blank" rel="noreferrer">Clone Hero</a> in Remakes / Recreations. Feature-rich Guitar Hero clone, thousands of songs + playlists, no lag, works with all guitar controllers, and supports MIDI drum kits.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#party-multiplayer" target="_blank" rel="noreferrer">Gidd</a> in Multiplayer Browser Games. Has quality versions of things like Monopoly, GeoGuessr, card games, etc.</p></li><li><p>Starred <a href="https://fmhy.net/system-tools#virtual-machines" target="_blank" rel="noreferrer">QEMU</a> in Virtual Machines. Performs well on non-Windows systems; best used with Virt-Manager or Vagrantup.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-backup" target="_blank" rel="noreferrer">Restic</a> in File Backup. Easy to use, multi-platform, and performed well in benchmarks.</p></li><li><p>Starred <a href="https://fmhy.net/ai#coding-ais" target="_blank" rel="noreferrer">Gemini CLI</a> in Coding AIs. This seems to have some of the best limits as of now.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed CrocDB as they&#39;ve been <a href="https://i.ibb.co/RpDvJFgf/image.png" target="_blank" rel="noreferrer">hit by DMCA</a> / <a href="https://i.imgur.com/iSV0MHq.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Removed the IcebergCharts website as they&#39;ve been <a href="https://i.ibb.co/XxMMwqDk/image.png" target="_blank" rel="noreferrer">hacked a few times now</a> / <a href="https://i.imgur.com/MkvElvr.png" target="_blank" rel="noreferrer">2</a>, and can&#39;t figure out why it&#39;s happening. We may re-add it in the future if they figure it out. Note that we&#39;ll keep the subreddit in its place for now.</p></li><li><p>Removed CanvasBlocker as it&#39;s Firefox-only, and FF has this built-in now; it can also apparently make fingerprinting worse in some cases and isn&#39;t maintained well anymore.</p></li><li><p>Removed FTV and WAC from Live Sports as both are now gone.</p></li><li><p>Removed Foxified as it&#39;s suddenly <a href="https://i.ibb.co/4RzPsQ8Z/image.png" target="_blank" rel="noreferrer">filling results with ads</a> / <a href="https://i.imgur.com/AjBMdfX.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Unstarred OnTheSpot as it will be losing Spotify support soon.</p></li><li><p>Unstarred Windsurf in Coding AIs as its limits and free models aren&#39;t as good anymore.</p></li></ul>',9))])}const b=t(l,[["render",h]]);export{c as __pageData,b as default};
